{
 "research_concepts": [
  "lineup coverage",
  "structural roles (organizer, shaper, terminal)",
  "talent assessment",
  "separability of effects",
  "within-team variation",
  "confounding variables"
 ],
 "methodological_questions": [
  "how to define and measure player structural roles",
  "how to measure lineup composition based on roles",
  "how to control for player talent in statistical models",
  "what statistical methods demonstrate separability of effects",
  "how to analyze within-team variation",
  "reliability of derived labels"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-CHT-009",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Superstar PPP can be suppressed by specific lineups and forced play types (e.g., Jokic vs MIN lineup PPP 0.814, -0.385 (n=59))."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Observed non-decaying lifts in play-type actions collapsed under within-team baseline, indicating a team-quality confound."
  },
  {
   "id": "FAM:SF-APPS-036",
   "status_as_recorded": "supported",
   "finding": "Mean PPP gap of +0.427 for BEST vs AVOID ranked counters when filtered to initiating player (38/94 players at n>=15; only 3 at n>=30 both tiers)."
  },
  {
   "id": "FAM:SF-APPA-017",
   "status_as_recorded": "rejected",
   "finding": "Routing possessions to each play type's best player initially showed value (+0.94 pts/100) but shrunk to +0.03 pts/100 on a larger sample (520 matchups) and did not survive defensive attention adaptation."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "High rates of within-game and cross-game defensive scheme change (61-67%) were found, but inferred labels could not separate real adjustments from offensive execution, with near-uniform transition matrices consistent with label noise."
  },
  {
   "id": "FAM:SF-PAP-024",
   "status_as_recorded": "rejected",
   "finding": "No significant correlation between structural influence concentration and defensive vulnerability (rho=+0.079 p=0.0882 CI[-0.114,+0.234])."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-CHT-009",
   "what_failed": "Observing superstar suppression by lineup and forced play type without robust controls.",
   "why": "E_unclear, RISK:PLACEBO_DEPENDENCE; No placebo or matching; later work treated similar gaps as artifacts."
  },
  {
   "id": "FAM:SF-APPA-045",
   "what_failed": "Comparing joint vs sequential Rank-then-Route ranking for play type and player selection.",
   "why": "LIM:small_sample, RISK:SAMPLE_SIZE_POWER; Mean +0.020 PPP left on table is small; sequential declared safe ~80%."
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Testing persistent impact score level 1 gate for play-type actions.",
   "why": "C_artifact, LIM:confounding, RISK:CONFOUNDING; Flat non-decaying lifts collapsed under within-team baseline; team-quality confound."
  },
  {
   "id": "FAM:SF-APPA-048",
   "what_failed": "Exploratory analysis of player-level BEST vs AVOID H2 PPP gaps.",
   "why": "A_unanswerable, RISK:PLACEBO_DEPENDENCE; n is small for most players (single-game playsheets); no multiplicity or clustered test."
  },
  {
   "id": "FAM:SF-APPS-009",
   "what_failed": "Comparing V4 vs V5 player routing direct scoring.",
   "why": "A_unanswerable, LIM:small_sample, RISK:DRIFT_NONSTATIONARITY, RISK:SAMPLE_SIZE_POWER; Scoreable 0 of 8 divergences; V5 mostly routed to 'team'."
  },
  {
   "id": "FAM:SF-APPS-036",
   "what_failed": "Player-level BEST vs AVOID PPP gap (initiators, 55-series) for star players.",
   "why": "LIM:small_sample, RISK:SAMPLE_SIZE_POWER; Most star cells are below the n>=30 gate."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Measuring defensive scheme change within game and across games using inferred labels.",
   "why": "A_unanswerable, LIM:label_or_classification_error, RISK:LABEL_ERROR; Inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise."
  },
  {
   "id": "FAM:SF-APPA-025",
   "what_failed": "Agent sequential adaptation test (costly-hit / matchup-hit).",
   "why": "A_unanswerable, LIM:small_sample, RISK:SAMPLE_SIZE_POWER; n=6; agent emphasized CUT in 6/6, consistent with generic advice."
  }
 ],
 "evidence_establishes": [
  "Player-level performance metrics (like PPP gaps) can be observed, but often suffer from small sample sizes at granular levels (FAM:SF-APPS-036).",
  "Controlling for confounding variables, especially team quality, is crucial to avoid artifacts (FAM:SF-CHT-029).",
  "Initial positive findings may not hold up under more robust analysis or larger samples (FAM:SF-APPA-017).",
  "The reliability of derived/inferred labels for complex concepts (like 'defensive scheme change') can be a significant risk (FAM:SF-APPA-005).",
  "Some hypotheses involving 'structural' concepts might lead to null results even with adequate power (FAM:SF-PAP-024)."
 ],
 "evidence_does_not_establish": [
  "Whether 'organizer, shaper, terminal' roles are reliably measurable and distinct from general player talent.",
  "Specific methods for disentangling lineup role coverage effects from player talent/counts.",
  "The existence or magnitude of 'talent control behaves' in the context of structural roles.",
  "The optimal statistical methodology for analyzing within-team variation of lineup coverage while controlling for talent."
 ],
 "own_inferences": [
  "The definition and accurate assignment of 'organizer, shaper, terminal' roles are critical and carry significant risk of label error or misclassification, similar to inferred defensive schemes.",
  "Controlling for player talent will require sophisticated statistical techniques, likely including player fixed effects or detailed player skill metrics, to avoid confounding.",
  "The 'separability' claim implies a need for a model that can estimate the independent effects of role coverage and talent, likely through interaction terms or hierarchical modeling.",
  "The 'within-team' variation aspect necessitates a design that leverages multiple lineups from the same team, which may reduce available sample sizes for specific lineup configurations."
 ],
 "uncertainties": [
  "The precise definitions and operationalization of 'organizer, shaper, terminal' roles from the available play-type data are not described.",
  "How 'talent/counts' will be measured and controlled for is not specified.",
  "The specific statistical model intended to demonstrate 'separability' and 'talent control behaves' is not outlined.",
  "The minimum sample size (e.g., number of possessions or minutes) required for a lineup to be included in the analysis is not defined, which impacts power."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence, particularly FAM:SF-CHT-029 (confounding), FAM:SF-APPA-005 (label error for inferred concepts), and FAM:SF-APPA-017 (powered null after robust analysis), highlights significant methodological risks related to confounding and label reliability for derived concepts. This shifts the decision from 'proceed' to 'proceed_with_changes' to explicitly address these risks in the design, particularly the need for robust role definitions, strong controls for talent, and careful statistical modeling to demonstrate separability."
 },
 "testability": {
  "p_testable": 0.6,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "The structural roles (organizer, shaper, terminal) are derived labels. Their reliability and accuracy from play-type data are a major concern, as seen in FAM:SF-APPA-005 regarding defensive schemes."
   },
   {
    "code": "CONFOUNDING",
    "text": "Separating the impact of role coverage from player talent/counts is inherently difficult. Talent is a strong confounder, as demonstrated by FAM:SF-CHT-029 where team quality confounded play-type effects."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [
   "FAM:SF-PAP-024"
  ],
  "summary": "While FAM:SF-PAP-024 explored 'structural concentration,' it did not address the specific question of lineup coverage by 'organizer, shaper, terminal' roles, their separability from talent, or within-team variation. Other retrieved studies touched on player/lineup effects and confounding but not this specific composite question."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The definitions and assignments of 'organizer, shaper, terminal' roles from play-type data are derived labels. Misclassification or inherent ambiguity in these labels could invalidate the analysis of lineup coverage and its separability."
  },
  {
   "code": "CONFOUNDING",
   "text": "Player talent is a strong confounder. Without adequate control, any observed effect of structural role coverage could simply be attributed to the talent level of the players filling those roles. This is central to the 'separable from talent/counts' claim."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "Analyzing 'within-team' variation for specific lineup compositions (e.g., >=1 organizer, shaper, terminal) might lead to small sample sizes for certain configurations, making it difficult to achieve sufficient statistical power, as highlighted in FAM:SF-APPS-036 and FAM:SF-APPA-048."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "If various definitions or thresholds for 'organizer, shaper, terminal' are explored, or if many different talent control methods are attempted, there is a risk of false positives from multiple testing."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The reliability and consistency of the 'organizer, shaper, terminal' role assignments over time and across different player contexts need to be established to ensure the measures are stable."
  },
  {
   "code": "MECHANICAL_FLOOR",
   "text": "The 'talent control behaves' aspect might imply that talent has a consistent effect. However, there could be mechanical floors or ceilings on player performance or role impact that limit the observed range of effects, especially when controlling for high-talent players."
  }
 ],
 "predicted_outcome": {
  "supported": 0.2,
  "rejected": 0.4,
  "untestable": 0.2,
  "artifact": 0.1,
  "uncertain": 0.1
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of lineup structural role coverage (presence of >=1 organizer, shaper, terminal) on offensive efficiency (PPP) or defensive effectiveness, conditional on player talent and other confounding factors, within teams.",
  "unit": "Possession (primary) and Lineup-Game-Segment (secondary for aggregation).",
  "sample": "NBA 2022-23, 2023-24, 2024-25, and complete 2025-26 regular seasons and playoffs. All possessions where structural roles can be identified. A minimum of 50 possessions for any specific lineup configuration to be included in analysis to mitigate SAMPLE_SIZE_POWER.",
  "power": "Target statistical power of 0.8 to detect a minimum effect size of 0.05 PPP difference, using a significance level of alpha=0.05. Power analysis will be conducted based on observed variance in PPP for different lineup types and after controlling for talent, using the 420,993 possessions and 90 team-seasons available.",
  "controls": "Player talent will be controlled using a combination of player fixed effects (for within-team analysis) and player-level composite metrics (e.g., RPM, EPM, or a custom talent metric derived from historical performance, if available and validated). Game-level controls will include opponent strength, score margin, game context (regular season/playoffs), and home/away status. Within-team analysis will utilize player substitution patterns and on/off court data to isolate lineup effects, potentially employing a difference-in-differences approach or hierarchical models with team and player random effects. The definition of 'organizer, shaper, terminal' roles must be rigorously validated against expert consensus or by demonstrating predictive power in other contexts, to mitigate LABEL_ERROR. A placebo test will be designed by randomly assigning 'fake' roles to players with similar usage patterns and testing for effects.",
  "falsification": "A falsification test will involve attempting to find effects of structural roles in situations where they are theoretically not expected (e.g., on metrics unrelated to offensive/defensive structure, or in lineups with intentionally misassigned roles). Additionally, testing whether talent controls 'behave' will involve verifying that talent metrics show expected correlations with performance and that their inclusion in the model significantly reduces unexplained variance, without absorbing the hypothesized role effects.",
  "multiplicity": "Given the exploratory nature of defining 'structural roles' and 'talent control behaves', primary hypotheses will be clearly stated. Any secondary or exploratory analyses will be clearly identified, and p-values adjusted using methods like Benjamini-Hochberg for False Discovery Rate control if multiple related tests are performed on the same dataset.",
  "decision_rule": "The research question will be considered 'supported' if a statistically significant (p < 0.05) and practically meaningful effect of lineup coverage by structural roles (>=1 organizer, shaper, terminal) is observed, after rigorous control for player talent and other confounders, and the 'talent control behaves' condition is met (i.e., talent effects are consistent and separable). The role definitions must also pass validation tests. If no such effect is found despite adequate power, it will be 'rejected'. If significant risks (e.g., LABEL_ERROR, CON-FOUNDING) cannot be mitigated or power is insufficient, it will be 'untestable' or 'artifact'.",
  "data_version": "NBA 2022-23 to 2025-26 (complete as of 2026-06-21) play-by-play, substitution rotations, starters, defensive matchup minutes, box-score summary, and derived play-type possession records."
 }

